from h import *
O=[]
O.append(R(6345810,None,
("سلطة كرنب بروكسل","يُفضّل تحضير هذه الوصفة قبل يوم (أو قبل عدة ساعات) حتى يتشرّب كرنب بروكسل الصلصة جيدًا، لكن يمكن تقديمها فورًا عند الحاجة.","9","½ كوب",
["6 أكواب ماء","1 رطل كرنب بروكسل طازج","2 عود بصل أخضر (مفروم ناعمًا)","¼ كوب خل نبيذ الأرز","1 ملعقة كبيرة خردل ديجون","1 ملعقة كبيرة صلصة صويا قليلة الصوديوم","2 ملعقة كبيرة بديل سكر قليل السعرات","¼ كوب مايونيز خفيف","¼ ملعقة صغيرة فلفل أسود","½ كوب لوز شرائح (محمّص)"],
["في قدر كبيرة، أحضر 6 أكواب من الماء إلى الغليان. أضف كرنب بروكسل وأنضجه جزئيًا في الماء المغلي لمدة دقيقة واحدة. أخرجه من الماء المغلي واشطفه بماء بارد لإيقاف الطهي. جفّف الكرنب بمنشفة نظيفة.","اقطع جذع كرنب بروكسل وشقّه إلى نصفين بالطول. باستخدام شفرة التقطيع في محضّر الطعام، عالج كرنب بروكسل ليتقطّع شرائح رفيعة. يمكنك أيضًا استخدام الجانب القاطع من المبشرة أو سكين حادة جدًا.","في وعاء متوسط، اخفق البصل الأخضر والخل والخردل وصلصة الصويا والمُحلّي قليل السعرات أو الخالي منها والمايونيز والفلفل الأسود معًا.","أضف كرنب بروكسل المقطّع واللوز المحمّص إلى الصلصة وامزج جيدًا."],[],[])))
O.append(R(6346471,
("Saltado peruano de pollo","El saltado peruano se prepara tradicionalmente con carne de res, pero esta versión más saludable usa pollo sin perder los sabores tradicionales. Es una receta rústica, rápida y reconfortante que se puede duplicar fácilmente para una reunión (o para tener sobras).","4","1 taza",
["1 libra de filetes de pechuga de pollo","1/4 de cucharadita de sal","1/4 de cucharadita de pimienta negra","3 cucharaditas de aceite de oliva (divididas)","1 cebolla morada entera (en rodajas finas)","2 tomates grandes (aprox. 1 libra) (sin el centro, partidos por la mitad y en rodajas)","2 dientes de ajo (picados)","2 cucharaditas de salsa de soya baja en sodio","2 cucharaditas de vinagre de vino tinto"],
["Espolvoree el pollo con la sal y la pimienta. Caliente 2 cucharaditas de aceite en una sartén antiadherente grande a fuego medio-alto. Agregue el pollo y cocínelo hasta que se dore, unos 6 minutos. Páselo a un plato.","Agregue la cebolla y la cucharadita de aceite restante y cocine, revolviendo de vez en cuando, hasta que se ablande, unos 5 minutos. Agregue los tomates, el ajo, la salsa de soya y el vinagre, y cocine, revolviendo de vez en cuando, hasta que los tomates se ablanden, unos 5 minutos.","Regrese el pollo a la sartén y caliéntelo bien."],[],[]),
("سالتادو الدجاج البيروفي","يُحضَّر السالتادو البيروفي تقليديًا بلحم البقر، لكن هذه النسخة الأكثر صحة تستخدم الدجاج دون التخلي عن النكهات التقليدية. وصفة ريفية سريعة ومريحة يمكن مضاعفتها بسهولة لتكفي عددًا أكبر من الضيوف (أو للاحتفاظ بالفائض).","4","1 كوب",
["1 رطل شرائح صدور الدجاج","¼ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود","3 ملاعق صغيرة زيت زيتون (مقسّمة)","1 حبة بصل أحمر (مقطّعة شرائح رفيعة)","2 حبة طماطم كبيرة (حوالي 1 رطل) (منزوعة القلب ومقسومة إلى نصفين ومقطّعة شرائح)","2 فص ثوم (مفروم)","2 ملعقة صغيرة صلصة صويا قليلة الصوديوم","2 ملعقة صغيرة خل النبيذ الأحمر"],
["رشّ الدجاج بالملح والفلفل. سخّن 2 ملعقة صغيرة من الزيت في مقلاة كبيرة غير لاصقة على نار متوسطة إلى عالية. أضف الدجاج واطهه حتى يحمرّ، حوالي 6 دقائق. انقله إلى طبق.","أضف البصل وملعقة الزيت الصغيرة المتبقية (1 ملعقة صغيرة) واطهه مع التحريك من حين لآخر حتى يذبل، حوالي 5 دقائق. أضف الطماطم والثوم وصلصة الصويا والخل، واطهه مع التحريك من حين لآخر حتى تلين الطماطم، حوالي 5 دقائق.","أعد الدجاج إلى المقلاة وسخّنه جيدًا."],[],[])))
O.append(R(6347356,
("Arroz frito de coliflor con pollo","Este arroz frito de coliflor con pollo es una excelente opción baja en carbohidratos cuando se le antoja comida asiática. Con arroz de coliflor y verduras frescas, es una cena colorida y nutritiva que se prepara con facilidad.","4","1 taza",
["2 cucharadas de aceite de aguacate","2 cucharaditas de jengibre fresco (picado)","2 dientes de ajo (picados)","1 taza de verduras mixtas (como guisantes, zanahorias, maíz, pimientos; picadas)","1 cabeza de coliflor (rallada o picada en granos de arroz)","2 cucharadas de salsa de soya baja en sodio","1 cucharadita de aceite de ajonjolí","1 taza de pechuga de pollo sin hueso ni piel (cocida, en cubos)","1 huevo grande (batido)","3 tallos de cebolla de cambray (picados, para decorar)"],
["En una sartén antiadherente grande o en un wok, caliente 1 cucharada de aceite a fuego medio-alto.","Agregue el jengibre y el ajo picados y saltéelos durante aproximadamente 1 minuto, hasta que desprendan aroma.","Agregue a la sartén las verduras mixtas, el arroz de coliflor, la salsa de soya y el aceite de ajonjolí, y saltee revolviendo constantemente durante 7-8 minutos, hasta que esté cocido y dorado en algunas partes.","Incorpore el pollo en cubos a la sartén.","Empuje la mezcla hacia un lado de la sartén y agregue la cucharada de aceite restante en el espacio vacío. Vierta los huevos batidos en ese espacio. Revuelva los huevos hasta que apenas estén cocidos. Mezcle los huevos con la mezcla de verduras y pollo.","Termine con la cebolla de cambray."],[],[]),
("أرز القرنبيط المقلي بالدجاج","أرز القرنبيط المقلي بالدجاج خيار رائع قليل الكربوهيدرات عندما تشتهي الطعام الآسيوي. بفضل أرز القرنبيط والخضار الطازجة، هو عشاء ملوّن ومغذٍّ وسهل التحضير.","4","1 كوب",
["2 ملعقة كبيرة زيت أفوكادو","2 ملعقة صغيرة زنجبيل طازج (مفروم)","2 فص ثوم (مفروم)","1 كوب خضار مشكّلة (مثل البازلاء والجزر والذرة والفلفل الرومي؛ مقطّعة)","1 رأس قرنبيط (مبشور أو مفروم بحجم حبات الأرز)","2 ملعقة كبيرة صلصة صويا قليلة الصوديوم","1 ملعقة صغيرة زيت سمسم","1 كوب صدور دجاج بدون عظم وبدون جلد (مطبوخة، مقطّعة مكعبات)","1 بيضة كبيرة (مخفوقة)","3 عود بصل أخضر (مفروم، للتزيين)"],
["في مقلاة كبيرة غير لاصقة أو ووك، سخّن 1 ملعقة كبيرة من الزيت على نار متوسطة إلى عالية.","أضف الزنجبيل والثوم المفرومين وقلّبهما لمدة دقيقة واحدة تقريبًا حتى تفوح رائحتهما.","أضف الخضار المشكّلة وأرز القرنبيط وصلصة الصويا وزيت السمسم إلى المقلاة وقلّب لمدة 7-8 دقائق حتى تنضج ويحمرّ بعضها.","أضف الدجاج المقطّع مكعبات إلى المقلاة وقلّب.","ادفع الخليط إلى جانب المقلاة وأضف ملعقة الزيت الكبيرة المتبقية (1 ملعقة كبيرة) في المساحة الفارغة. اسكب البيض المخفوق في المساحة الفارغة. قلّب البيض حتى ينضج بالكاد. امزج البيض مع خليط الخضار والدجاج.","أنهِ الطبق بالبصل الأخضر."],[],[])))
O.append(R(6348205,None,
("قطع لحم الضأن مع البطاطس والخضار الربيعية","لحم الضأن مثالي لموسم عيد الفصح وهو طبق مميز في أي وقت آخر من السنة. قطع ضلع الضأن قطعة طرية وقليلة الدهن يسهل شيّها. وهي خيار جيد لتجربته عندما تملّ من الدجاج واللحم البقري المعتادين. قدّمها مع خضار الربيع مثل الهليون والجزر.","4","1-2 قطعة ضأن + 1 حبة بطاطس و5 أعواد هليون و2 جزرة",
["1 ملعقة كبيرة + 2 ملعقة صغيرة زيت زيتون بكر ممتاز (مقسّم)","2 فص ثوم (مفروم)","½ ملعقة صغيرة ملح خشن","¼ ملعقة صغيرة فلفل أسود","3 ملاعق كبيرة إكليل الجبل (روزماري) طازج (مفروم، مقسّم)","1 رطل قطع ضلع ضأن قليلة الدهن (منزوعة الدهن)","1 بخّة، 0.25 جم بخاخ طهي غير لاصق","4 حبات بطاطس حمراء صغيرة (مقطّعة أرباعًا مع القشرة)","8 جزرات متوسطة (مقسومة إلى نصفين)","1 حزمة هليون (حوالي 20 عودًا، مقطوعة الأطراف)"],
["اخلط 1 ملعقة كبيرة من زيت الزيتون مع الثوم والملح والفلفل وإكليل الجبل. غطِّ قطع الضأن بالكامل بالخليط ودعها تتتبّل لمدة ساعتين في الثلاجة. أخرجها من الثلاجة قبل الشيّ بـ 30 دقيقة.","سخّن الفرن مسبقًا إلى 450° فهرنهايت (230° مئوية). رشّ صينية الخبز ببخاخ الطهي.","ضع البطاطس في وعاء وقلّبها مع 1 ملعقة صغيرة من زيت الزيتون و2 ملعقة كبيرة من إكليل الجبل المفروم. ضعها على الصينية وضع الصينية في وسط الفرن المسخّن مسبقًا وحمّصها لمدة 10 دقائق.","في الوعاء نفسه، ضع الجزر وقلّبه مع باقي الزيت وإكليل الجبل. أضفه إلى البطاطس مع الهليون وواصل التحميص لمدة 10 دقائق.","في الأثناء، سخّن الشواية وضع قطع الضأن مباشرة عليها. اشوِها لمدة 5 دقائق، ثم اقلب القطع وواصل الشيّ لمدة 3 – 5 دقائق. يجب أن تصل درجة الحرارة الداخلية إلى 135° فهرنهايت (55° مئوية)."],[],[])))
O.append(R(6349071,None,
("شوربة الدجاج والأرز البري","الأرز البري حبوب كاملة وخيار أكثر صحة من الأرز الأبيض. هذه الشوربة مشبعة ومثالية لأيام الشتاء الباردة.","9","حوالي 1 كوب",
["2 ملعقة صغيرة سمن نباتي (مارجرين) خالٍ من الدهون المتحولة","1 حبة بصل متوسطة (مقطّعة مكعبات)","2 جزرة متوسطة (مقطّعة مكعبات)","2 عود كرفس (مقطّع مكعبات)","1 كوب فطر أبيض (شامبينيون) (مقطّع مكعبات)","44 أونصة مرق دجاج قليل الصوديوم (خالٍ من الدهون)","1 كوب ماء (+ 1 ملعقة كبيرة ماء بارد، مقسّم)","¼ ملعقة صغيرة زعتر مجفف","¼ ملعقة صغيرة فلفل أسود","¼ ملعقة صغيرة ملح (اختياري)","1 ملعقة كبيرة نشا الذرة","1 كوب أرز بري","2 كوب دجاج مطبوخ (مقطّع مكعبات)"],
["ذوّب السمن النباتي في قدر شوربة كبيرة على نار متوسطة إلى عالية. أضف البصل وقلّبه لمدة 3 دقائق أو حتى يصبح شفافًا. أضف الجزر والكرفس والفطر وقلّبها لمدة 5 دقائق.","أضف مرق الدجاج والماء والزعتر والفلفل الأسود والملح.","في كوب صغير، امزج نشا الذرة مع 1 ملعقة كبيرة من الماء البارد. أضف الخليط إلى الشوربة.","أحضرها إلى الغليان ثم أضف الأرز وقلّب.","خفّف النار وغطِّ القدر واتركها على نار هادئة لمدة 45 دقيقة. أضف الدجاج المطبوخ وقلّب جيدًا."],[],[])))
O.append(R(6349432,
("Aguacate relleno de 4 capas","Los aguacates están llenos de grasas monoinsaturadas saludables para el corazón y son una fuente de fibra baja en carbohidratos. Aquí cubrimos una mitad de aguacate con frijoles negros y salsa para un aperitivo o guarnición sencillo al estilo del suroeste. Puede usar su salsa envasada favorita o probar esta receta de salsa casera Casi Suave.","4","1 mitad de aguacate",
["1/3 de taza de frijoles negros (escurridos y enjuagados)","2 aguacates medianos","4 cucharadas de yogur griego natural sin grasa","4 cucharadas de salsa","4 cucharaditas de queso cheddar o estilo mexicano rallado reducido en grasa","1/4 de cucharadita de sal","2 cucharaditas de jugo de limón verde fresco"],
["Ponga los frijoles en un tazón pequeño. Con el reverso de un tenedor, macháquelos hasta que tengan una consistencia casi suave.","Corte los aguacates por la mitad y quíteles el hueso. En el centro de cada mitad, coloque en capas 1 cucharada de frijoles, 1 cucharada de yogur griego y 1 cucharada de salsa, y espolvoree con 1 cucharadita de queso. Espolvoree la sal de manera uniforme sobre los aguacates. Sirva cada mitad de aguacate con 1 rodaja de limón para exprimir sobre el plato."],[],[]),
("أفوكادو محشي بأربع طبقات","الأفوكادو غني بالدهون الأحادية غير المشبعة الصحية للقلب، وهو مصدر للألياف قليل الكربوهيدرات. هنا نغطي نصف حبة أفوكادو بالفاصولياء السوداء والصلصة (السالسا) للحصول على وجبة خفيفة أو طبق جانبي بسيط بنكهة الجنوب الغربي. يمكنك استخدام صلصتك المعلّبة المفضلة، أو تجربة وصفة السالسا المنزلية شبه الناعمة.","4","نصف حبة أفوكادو",
["⅓ كوب فاصولياء سوداء (مصفاة ومشطوفة)","2 حبة أفوكادو متوسطة","4 ملاعق كبيرة زبادي يوناني سادة خالٍ من الدسم","4 ملاعق كبيرة صلصة سالسا","4 ملاعق صغيرة جبن شيدر أو جبن بنكهة مكسيكية مبشور قليل الدسم","¼ ملعقة صغيرة ملح","2 ملعقة صغيرة عصير ليمون أخضر طازج"],
["ضع الفاصولياء في وعاء صغير. باستخدام ظهر الشوكة، اهرسها حتى تصبح شبه ناعمة.","اقطع حبات الأفوكادو إلى نصفين وانزع النوى. في وسط كل نصف، ضع طبقات من 1 ملعقة كبيرة من الفاصولياء و1 ملعقة كبيرة من الزبادي اليوناني و1 ملعقة كبيرة من الصلصة، ثم رشّ 1 ملعقة صغيرة من الجبن. رشّ الملح بالتساوي على الأفوكادو. قدّم كل نصف أفوكادو مع شريحة ليمون واحدة لعصرها على الطبق."],[],[])))
O.append(R(6350887,
("Salsa de aguacate y frijoles negros","Prepárese para darle un toque picante a su ensalada con esta ensalada de aguacate y frijoles negros de inspiración tex-mex. Colorida y fresca, prepárela la próxima vez que quiera una opción para el martes de tacos apta para personas con diabetes.","6","3/4 de taza",
["2 latas (de 15 onzas) de frijoles negros (bajos en sodio, escurridos y enjuagados)","1 aguacate mediano (en cubos)","1 taza de maíz (granos enteros)","1 taza de tomates roma (en cubos)","1/2 taza de cebolla morada (finamente picada)","1/4 de taza de cilantro fresco (picado, más un poco para decorar)","1 chile jalapeño entero (sin semillas y finamente picado)","2 cucharadas de jugo de limón verde","2 cucharadas de aceite de oliva extra virgen","1 cucharadita de comino molido","1/4 de cucharadita de sal","1/2 cucharadita de pimienta negra"],
["En un tazón grande, combine los frijoles negros, el aguacate en cubos, los granos de maíz, los tomates en cubos, la cebolla morada finamente picada, el cilantro fresco picado y el jalapeño finamente picado.","En un tazón pequeño, bata el jugo de limón verde, el aceite de oliva extra virgen, el comino molido, la sal y la pimienta negra.","Vierta el aderezo sobre la ensalada y mezcle suavemente para que quede bien cubierta.","Deje reposar la ensalada en el refrigerador durante 10 minutos para que se integren los sabores.","Antes de servir, mezcle la ensalada una vez más. Decore con cilantro fresco si lo desea."],[],[]),
("سالسا الأفوكادو والفاصولياء السوداء","استعد لإضفاء نكهة حارة على سلطتك مع سلطة الأفوكادو والفاصولياء السوداء المستوحاة من المطبخ التكسي-مكسيكي. ملوّنة وطازجة، جرّبها في المرة القادمة التي ترغب فيها بخيار لثلاثاء التاكو مناسب لمرضى السكري.","6","¾ كوب",
["2 علبة (15 أونصة) فاصولياء سوداء (قليلة الصوديوم، مصفاة ومشطوفة)","1 حبة أفوكادو متوسطة (مقطّعة مكعبات)","1 كوب ذرة (حبوب كاملة)","1 كوب طماطم روما (برقوقية) (مقطّعة مكعبات)","½ كوب بصل أحمر (مفروم ناعمًا)","¼ كوب كزبرة خضراء طازجة (مفرومة، مع كمية إضافية للتزيين)","1 حبة فلفل هالابينو كاملة (منزوعة البذور ومفرومة ناعمًا)","2 ملعقة كبيرة عصير ليمون أخضر","2 ملعقة كبيرة زيت زيتون بكر ممتاز","1 ملعقة صغيرة كمون مطحون","¼ ملعقة صغيرة ملح","½ ملعقة صغيرة فلفل أسود"],
["في وعاء كبير، اخلط الفاصولياء السوداء والأفوكادو المقطّع مكعبات وحبوب الذرة والطماطم المقطّعة مكعبات والبصل الأحمر المفروم ناعمًا والكزبرة الخضراء الطازجة المفرومة والهالابينو المفروم ناعمًا.","في وعاء صغير، اخفق عصير الليمون الأخضر وزيت الزيتون البكر الممتاز والكمون المطحون والملح والفلفل الأسود معًا.","اسكب الصلصة على السلطة وقلّبها برفق ليتغطى كل شيء بالتساوي.","اترك السلطة تتتبّل في الثلاجة لمدة 10 دقائق لتتمازج النكهات.","قبل التقديم، قلّب السلطة مرة أخرى. زيّنها بالكزبرة الخضراء الطازجة إن رغبت."],[],[])))
O.append(R(6352574,
("Requesón con piña y nueces","¡Lleve su requesón a otro nivel con esta receta! Agregue hojas de menta encima para darle más frescura.","2","1 ¼ tazas",
["1 taza de requesón (sin grasa)","1 taza de piña (en cubos)","2 cucharadas de nueces (picadas)"],
["En un tazón, mezcle el requesón, los trozos de piña fresca y las nueces picadas.","Divida la mezcla de requesón en tazones individuales. Sirva de inmediato y disfrute de este platillo refrescante y rico en proteínas."],[],[]),
("جبن قريش مع الأناناس والجوز","ارتقِ بجبن القريش إلى مستوى جديد مع هذه الوصفة! زيّنه بأوراق النعناع لمزيد من الانتعاش.","2","1 ¼ كوب",
["1 كوب جبن قريش (خالٍ من الدسم)","1 كوب أناناس (مقطّع مكعبات)","2 ملعقة كبيرة جوز (مفروم)"],
["في وعاء، اخلط جبن القريش وقطع الأناناس الطازج والجوز المفروم.","وزّع خليط جبن القريش على أوعية التقديم. قدّمه فورًا واستمتع بهذا الطبق المنعش الغني بالبروتين."],[],[])))
O.append(R(6352737,None,
("بيض مخلل محشو بالحمص","جرّب هذه النسخة المختلفة من البيض المحشي التقليدي. استبدل الصفار بخليط منعش من البقوليات لتقليل السعرات والدهون والكوليسترول. سيستمتع ضيوفك به بالقدر نفسه!","8","2 نصف بيضة",
["8 بيضات كبيرة (مسلوقة جيدًا ومقشّرة)","1 علبة (14.5 أونصة) حمص (مصفى ومشطوف)","2 فص ثوم","1 حبة ليمون صغيرة (مبشورة القشر ومعصورة)","1 ملعقة كبيرة زيت زيتون","¼ كوب مرق خضار قليل الصوديوم","¼ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود","¼ كوب صلصة سالسا","1 ملعقة كبيرة بقدونس طازج مفروم"],
["اقطع البيض المسلوق إلى نصفين بالطول وتخلّص من الصفار.","ضع الحمص والثوم وبشر الليمون وعصير الليمون وزيت الزيتون والمرق والملح والفلفل والسالسا والبقدونس في خلاط أو محضّر طعام. عالجها حتى يصبح الحمص ناعمًا.","احشُ كل نصف بيضة بملعقة كبيرة مكوّمة من الحمص."],[],[])))
O.append(R(6353740,
("Shakshuka de garbanzos","La shakshuka de garbanzos es una versión deliciosa y nutritiva de la shakshuka clásica. Para añadir más proteína de origen vegetal, se agregan garbanzos a este desayuno lleno de sabor.","4","1/4 de la sartén + 1/4 de pan pita pequeño",
["1 cucharada de aceite de oliva","1 cebolla amarilla mediana (picada)","3 dientes de ajo","1 cucharadita de comino","1 cucharadita de pimentón ahumado","1/2 cucharadita de cilantro molido","1 lata (de 14 onzas) de tomates en cubos (sin sal agregada)","1 lata (de 14 onzas) de garbanzos (bajos en sodio, escurridos y enjuagados)","1/4 de cucharadita de sal (dividida)","1/2 cucharadita de pimienta negra","4 huevos grandes","1 cucharada de albahaca fresca (picada, para decorar)","1 pan pita integral pequeño (cortado en cuartos)"],
["Caliente el aceite de oliva en una sartén grande a fuego medio.","Agregue la cebolla picada y cocínela hasta que se ablande, unos 5 minutos.","Añada el ajo picado y cocine 30 segundos más.","Espolvoree el comino molido, el pimentón y el cilantro molido sobre la cebolla y el ajo.","Vierta los tomates en cubos y los garbanzos. Sazone con ½ cucharadita de sal y de pimienta (de cada una). Cocine a fuego lento de 10 a 15 minutos, hasta que la mezcla espese.","Haga pequeños huecos en la mezcla y rompa un huevo en cada uno. Espolvoree con ½ cucharadita de sal.","Tape la sartén y cocine de 5 a 7 minutos, o hasta que las claras estén cuajadas pero las yemas todavía estén líquidas (ajuste el tiempo de cocción según su preferencia de cocción del huevo).","Decore con albahaca fresca picada y sirva con un trozo de pan pita."],[],[]),
("شكشوكة الحمص","شكشوكة الحمص نسخة شهية ومغذّية من الشكشوكة الكلاسيكية. ولإضافة مزيد من البروتين النباتي، يُضاف الحمص إلى هذا الفطور الغني بالنكهة.","4","¼ المقلاة + ¼ خبز بيتا صغير",
["1 ملعقة كبيرة زيت زيتون","1 حبة بصل أصفر متوسطة (مفرومة)","3 فص ثوم","1 ملعقة صغيرة كمون","1 ملعقة صغيرة بابريكا مدخنة","½ ملعقة صغيرة كزبرة مطحونة","1 علبة (14 أونصة) طماطم معلّبة مقطّعة مكعبات (بدون ملح مضاف)","1 علبة (14 أونصة) حمص معلّب (قليل الصوديوم، مصفى ومشطوف)","¼ ملعقة صغيرة ملح (مقسّمة)","½ ملعقة صغيرة فلفل أسود","4 بيضات كبيرة","1 ملعقة كبيرة ريحان طازج (مفروم، للتزيين)","1 رغيف بيتا صغير من القمح الكامل (مقطّع أرباعًا)"],
["سخّن زيت الزيتون في مقلاة كبيرة على نار متوسطة.","أضف البصل المفروم واطهه حتى يذبل، حوالي 5 دقائق.","أضف الثوم المفروم واطهه 30 ثانية أخرى.","رشّ الكمون المطحون والبابريكا والكزبرة المطحونة على البصل والثوم.","اسكب الطماطم المقطّعة والحمص. تبّل بـ ½ ملعقة صغيرة من الملح ومثلها من الفلفل. اتركها على نار هادئة لمدة 10–15 دقيقة حتى يتكاثف الخليط.","اصنع حفرًا صغيرة في الخليط واكسر بيضة في كل حفرة. رشّ ½ ملعقة صغيرة من الملح.","غطِّ المقلاة واطهِ لمدة 5–7 دقائق، أو حتى يتماسك بياض البيض بينما يبقى الصفار سائلًا (اضبط وقت الطهي بحسب درجة نضج البيض التي تفضّلها).","زيّنه بالريحان الطازج المفروم وقدّمه مع قطعة من خبز البيتا."],[],[])))
O.append(R(6354484,None,
("سلطة على طريقة السيزر بالفلفل والفستق مع الدجاج","هذه السلطة الرئيسية تتناسب تمامًا مع خبز الثوم كطبق جانبي. يمكنك أيضًا شيّ الدجاج وتحضير الصلصة مسبقًا لتعبئتها كغداء خلال الأسبوع.","4","2 كوب",
["4 فخذ دجاج بدون عظم وبدون جلد (3 أونصات لكل واحدة)","2 ملعقة صغيرة زيت الكانولا","⅛ ملعقة صغيرة ملح خشن","⅓ كوب حمص","3 ملاعق كبيرة شاي أخضر غير محلّى (بارد)","2½ ملعقة كبيرة جبن بارميجيانو ريجيانو (مبشور)","2 فص ثوم (فصوص كبيرة)","1 ملعقة كبيرة خردل ديجون","2 ملعقة صغيرة صلصة ورسترشير","2 ملعقة صغيرة عصير ليمون","1¼ ملعقة صغيرة حبوب فلفل أسود (مجروشة طازجة، مقسّمة)","8 أكواب خضروات ورقية مشكّلة (8 أونصات)","2 ملعقة كبيرة فستق (محمّص ومقشّر ومفروم، مملح قليلًا)"],
["سخّن شواية أو مقلاة شواء. دهن الدجاج بالزيت ورشّه بالملح. اشوِه على نار متوسطة مباشرة حتى ينضج تمامًا وتظهر علامات الشواء. ضعه جانبًا.","ضع الحمص والشاي والجبن والثوم والخردل وصلصة ورسترشير وعصير الليمون و1 ملعقة صغيرة من حبوب الفلفل في خلاط. غطِّه واخلط حتى يصبح ناعمًا.","عند التقديم، قلّب الصلصة مع الخضروات الورقية في وعاء خلط كبير. انقلها إلى 4 أوعية أو أطباق منفصلة، وضع فوقها الدجاج المشوي، ورشّ الفستق وباقي حبوب الفلفل (¼ ملعقة صغيرة)، ثم قدّمها."],[],[])))
O.append(R(6356142,None,
("مافن رغيف اللحم مع طبقة البطاطا الحلوة","هذه الوجبة الصحية سهلة جدًا ولذيذة. كما أنها تُخبز أسرع من رغيف اللحم الكبير بسبب صغر حجم المافن.","12","1 كعكة مافن",
["2 حبة بطاطا حلوة متوسطة","1 ملعقة كبيرة سمن نباتي (مارجرين) خالٍ من الدهون المتحولة","20 أونصة لحم ديك رومي مفروم قليل الدهن","1 بيضة كبيرة (مخفوقة قليلًا)","1 ملعقة كبيرة مسحوق التشيلي","¼ ملعقة صغيرة فلفل أسود","1 ملعقة صغيرة مسحوق الثوم","⅓ كوب بصل (مقطّع مكعبات صغيرة)","½ كوب دقيق الذرة أو الشوفان (شوفان خالٍ من الغلوتين إذا كنت تتبع نظامًا خاليًا من الغلوتين)","2 ملعقة كبيرة كاتشب"],
["سخّن الفرن مسبقًا إلى 425 درجة فهرنهايت (220° مئوية). بطّن قالب المافن بأكواب ورقية.","نظّف حبات البطاطا واثقبها عدة مرات بالشوكة. اخبزها في الفرن لمدة 20 دقيقة. أخرجها من الفرن وسخّنها في الميكروويف 5 دقائق إضافية أو حتى تلين. انزع القشر وضع البطاطا في وعاء متوسط. اهرسها بالمهراس واخفق معها السمن النباتي. امزج جيدًا.","في وعاء متوسط، امزج مكونات رغيف اللحم معًا.","ضع حوالي ¼ كوب من خليط رغيف اللحم في كل كوب مبطّن من قالب المافن. اخبزها لمدة 25 دقيقة.","ضع على كل مافن رغيف لحم مطبوخ مغرفة من البطاطا الحلوة."],[],[])))
O.append(R(6356826,None,
("كينوا بالسبانخ وصنوبر","هذا الطبق الجانبي الغني بالعناصر الغذائية يتناسب تمامًا مع السمك أو الدجاج أو لحم الخنزير.","6","½ كوب",
["1 كوب كينوا (جافة)","2 كوب مرق خضار قليل الصوديوم","1 ملعقة كبيرة زيت زيتون","2 فص ثوم (مفروم)","6 أونصات سبانخ صغيرة (بيبي)","¼ كوب صنوبر (محمّص)","⅛ ملعقة صغيرة فلفل أسود","2 ملعقة كبيرة جبن بارميزان (مبشور طازجًا)"],
["اطهِ الكينوا بحسب إرشادات العبوة مع مرق الدجاج.","سخّن زيت الزيتون في مقلاة على نار متوسطة إلى عالية. أضف الثوم وقلّبه لمدة 30 ثانية. أضف السبانخ وقلّبها لمدة 5 دقائق تقريبًا.","اسكب الكينوا المطبوخة في وعاء متوسط؛ أضف السبانخ وباقي المكونات وامزج جيدًا."],[],[])))
